import { GestureHandlerRootView } from 'react-native-gesture-handler';
import React from 'react';
import { Platform, LogBox } from 'react-native';
import { StatusBar } from 'expo-status-bar';
import { SafeAreaProvider } from 'react-native-safe-area-context';

import { GlobalStateProvider } from './src/context/GlobalState';
import { DependencyProvider } from './src/di/DependencyContext';
import AppNavigator from './src/navigation/AppNavigator';
import ErrorBoundary from './src/components/ErrorBoundary';

// Ignore development warnings from third-party libraries
LogBox.ignoreLogs([
  'props.pointerEvents is deprecated',
  'Failed to execute \'removeChild\' on \'Node\'',
  'An error occurred in the <div> component',
  'An error occurred in the <NativeSafeAreaProvider> component',
  'An error occurred in the <ModalPortal> component',
  '[Reanimated] Failed to create CSS stylesheet',
  'An iframe which has both allow-scripts and allow-same-origin',
]);

export default function App() {
  const RootContent = (
    <DependencyProvider>
      <GlobalStateProvider>
        <StatusBar style="light" />
        <ErrorBoundary>
          <AppNavigator />
        </ErrorBoundary>
      </GlobalStateProvider>
    </DependencyProvider>
  );

  return (
    <GestureHandlerRootView style={{ flex: 1 }}>
      <SafeAreaProvider>
        {RootContent}
      </SafeAreaProvider>
    </GestureHandlerRootView>
  );
}

import '@expo/metro-runtime';
import 'react-native-gesture-handler';
import { enableScreens } from 'react-native-screens';
import { registerRootComponent } from 'expo';

import App from './App';
enableScreens(false);

// registerRootComponent calls AppRegistry.registerComponent('main', () => App);
// It also ensures that whether you load the app in Expo Go or in a native build,
// the environment is set up appropriately
registerRootComponent(App);

import { apiGet, apiPost, apiPut, apiPatch, apiDelete, apiPostFormData, tokenService } from './httpClient';

export async function loginApi(usernameOrEmail, password) {
  await tokenService.clearTokens();
  const response = await apiPost('/api/v1/Auth/login', { usernameOrEmail, password }, undefined, false);
  const data = await response.json();
  if (!response.ok) {
    throw new Error(data.error?.message || data.title || 'Đăng nhập thất bại');
  }
  const payload = data.value || data;
  return {
    ...payload,
    accessToken: payload.accessToken || payload.AccessToken,
    refreshToken: payload.refreshToken || payload.RefreshToken,
  };
}

