	withRepeat,
	withTiming,
} from "react-native-reanimated";
import ScalePress from "../../components/ScalePress";

const { width } = Dimensions.get("window");

export default function QRScanScreen({ navigation }) {
	const scanPos = useSharedValue(0);
	const theme = useTheme();
	const styles = getStyles(theme); // Use the useTheme hook

	React.useEffect(() => {
		scanPos.value = withRepeat(withTiming(250, { duration: 2000 }), -1, true);
	}, []);

	const scanStyle = useAnimatedStyle(() => ({
		transform: [{ translateY: scanPos.value }], // This is fine
	}));

	return (
		<SafeAreaView
			style={[getStyles(theme).container, { backgroundColor: "#000" }]}
			edges={["top"]}
		>
			<View style={getStyles(theme).header}>
				<TouchableOpacity
					style={styles.backBtn}
					onPress={() => navigation.goBack()}
				>
					<ChevronLeft color="#fff" size={28} />
				</TouchableOpacity>
				<Text style={styles.headerTitle}>Quét mã QR</Text>
				<TouchableOpacity
					style={styles.backBtn}
					onPress={() =>
						navigation.navigate("CustomerHome", {
							screen: "Profile",
							params: { openSettings: true },
						})
					}
				>
					<Settings color="#fff" size={22} />
				</TouchableOpacity>
			</View>

			<View style={styles.content}>
				<Text style={[getStyles(theme).hintText, { color: "#fff" }]}>
					Hướng camera về phía mã QR trên xe hoặc giấy tờ
				</Text>

				<View style={getStyles(theme).scanFrameContainer}>
					<View
						style={[
							getStyles(theme).scanFrame,
							{ borderColor: theme.colors.border + "33" },
						]}
					>
						<Animated.View style={[styles.scanLine, scanStyle]} />

						{/* Corners */}
						<View style={[styles.corner, styles.topLeft]} />
						<View style={[styles.corner, styles.topRight]} />
						<View style={[styles.corner, styles.bottomLeft]} />
						<View style={[styles.corner, styles.bottomRight]} />
					</View>
				</View>

				<ScalePress
					style={[
						getStyles(theme).flashBtn,
						{ backgroundColor: theme.colors.border + "33" },
					]}
				>
					<Zap color="#fff" size={20} />
					<Text style={[getStyles(theme).flashText, { color: "#fff" }]}>
						Bật đèn Flash
					</Text>
				</ScalePress>
			</View>

			<View style={getStyles(theme).footer}>
				<Text
					style={[
						getStyles(theme).footerText,
						{ color: theme.colors.subtext + "80" },
					]}
				>
					Mã định danh xe giúp bạn truy cập nhanh lịch sử bảo trì và thông tin
					sở hữu.
				</Text>
			</View>
		</SafeAreaView>
	);
}

