import React, { useState, useEffect } from "react";
import {
	StyleSheet,
	Text,
	View,
	ScrollView,
	TouchableOpacity,
	Image,
} from "react-native";
import { SafeAreaView } from "react-native-safe-area-context";
import { ChevronLeft, Trash2, Bookmark, Settings } from "lucide-react-native";
import { useTheme } from "../../theme/Theme"; // Import useTheme
import GlassCard from "../../components/GlassCard";
import Animated, { FadeInDown } from "react-native-reanimated";
import AsyncStorage from "@react-native-async-storage/async-storage";
import ScalePress from "../../components/ScalePress";

export default function SavedNewsScreen({ navigation }) {
	const [savedItems, setSavedItems] = useState([]);
	const { theme, getStyles } = useTheme();
	const styles = getStyles(theme);

	const loadSavedNews = async () => {
		try {
			const stored = await AsyncStorage.getItem("saved_news");
			if (stored) {
				setSavedItems(JSON.parse(stored));
			}
		} catch (e) {
			console.log("Failed to load news", e);
		}
	};

	useEffect(() => {
		const init = async () => {
			await loadSavedNews();
		};
		init();
	}, []);

	const removeNews = async (id) => {
		try {
			const newList = savedItems.filter((item) => item.id !== id);
			setSavedItems(newList);
			await AsyncStorage.setItem("saved_news", JSON.stringify(newList));
		} catch (e) {
			console.log("Failed to remove news", e);
		}
	};

	return (
		<SafeAreaView
			style={[
				getStyles(theme).container,
				{ backgroundColor: theme.colors.background },
			]}
			edges={["top"]}
		>
			<View style={getStyles(theme).header}>
				<TouchableOpacity
					style={[
						getStyles(theme).backBtn,
						{ backgroundColor: theme.colors.card },
					]}
					onPress={() => navigation.goBack()}
				>
					<ChevronLeft color={theme.colors.text} size={28} />
				</TouchableOpacity>
				<Text
					style={[getStyles(theme).headerTitle, { color: theme.colors.text }]}
				>
					Tin đã lưu
				</Text>
				<TouchableOpacity
					style={[
						getStyles(theme).backBtn,
						{ backgroundColor: theme.colors.card },
					]}
					onPress={() =>
						navigation.navigate("CustomerHome", {
							screen: "Profile",
							params: { openSettings: true },
						})
					}
				>
					<Settings color="#fff" size={22} />
				</TouchableOpacity>
			</View>

			<ScrollView
				showsVerticalScrollIndicator={false}
				contentContainerStyle={styles.scrollContent}
			>
				{savedItems.length === 0 ? (
					<View style={getStyles(theme).emptyState}>
						<Bookmark color={theme.colors.subtext} size={64} opacity={0.3} />
						<Text
							style={[
								getStyles(theme).emptyText,
								{ color: theme.colors.subtext },
							]}
						>
							Bạn chưa lưu tin tức nào
						</Text>
						<TouchableOpacity
							style={[
								getStyles(theme).exploreBtn,
								{ backgroundColor: theme.colors.primary + "1A" },
							]}
							onPress={() => navigation.navigate("CustomerHome")}
						>
							<Text
								style={[
									getStyles(theme).exploreBtnText,
									{ color: theme.colors.primary },
								]}
							>
								Khám phá ngay
							</Text>
						</TouchableOpacity>
					</View>
				) : (
					savedItems.map((item, index) => (
						<Animated.View
							key={item.id}
							entering={FadeInDown.delay(index * 100)}
						>
							<GlassCard
								style={[
									getStyles(theme).newsCard,
									{
										borderColor: theme.colors.border,
										backgroundColor: theme.colors.card,
									},
								]}
								intensity={10}
							>
								<Image source={{ uri: item.image }} style={styles.newsImage} />
								<View style={styles.newsContent}>
									<Text
										style={[
											getStyles(theme).newsTitle,
											{ color: theme.colors.text },
										]}
									>
										{item.title}
									</Text>
									<View
										style={[
											getStyles(theme).newsFooter,
											{ borderTopColor: theme.colors.border },
										]}
									>
										<TouchableOpacity
											onPress={() => removeNews(item.id)}
											style={getStyles(theme).removeBtn}
										>
											<Trash2 color={theme.colors.secondary} size={18} />
											<Text
												style={[
													getStyles(theme).removeText,
													{ color: theme.colors.secondary },
												]}
											>
												Gỡ bỏ
											</Text>
										</TouchableOpacity>
									</View>
								</View>
							</GlassCard>
						</Animated.View>
					))
				)}
			</ScrollView>
		</SafeAreaView>
	);
}

const getStyles = (theme) =>
	StyleSheet.create({
		container: { flex: 1 },
		header: {
			flexDirection: "row",
			alignItems: "center",
			justifyContent: "space-between",
			paddingHorizontal: theme.spacing.md,
			height: 60,
		},
		backBtn: {
			width: 44,
			height: 44,
			justifyContent: "center",
			alignItems: "center",
			borderRadius: theme.radius.md,
		},
		headerTitle: { fontSize: 18, fontWeight: "bold" },

		scrollContent: { padding: theme.spacing.md, flexGrow: 1 },

		emptyState: {
			flex: 1,
			alignItems: "center",
			justifyContent: "center",
			marginTop: 100,
		},
		emptyText: { fontSize: 16, marginTop: 20 },
		exploreBtn: {
			marginTop: 20,
			paddingHorizontal: 25,
			paddingVertical: 12,
			borderRadius: theme.radius.full,
		},
		exploreBtnText: { fontWeight: "bold" },

		newsCard: {
			marginBottom: 20,
			overflow: "hidden",
			padding: 0,
			borderRadius: theme.radius.lg,
		},
		newsImage: { width: "100%", height: 150 },
		newsContent: { padding: theme.spacing.md },
		newsTitle: { fontSize: 16, fontWeight: "bold", marginBottom: 10 },
		newsFooter: {
			flexDirection: "row",
			justifyContent: "flex-end",
			borderTopWidth: 1,
			paddingTop: 10,
		},
		removeBtn: { flexDirection: "row", alignItems: "center" },
		removeText: { fontSize: 12, fontWeight: "bold", marginLeft: 6 },
	});

import React from 'react';
import {
  Text,
  View,
  ScrollView,
  TouchableOpacity,
  TextInput,
  Image
} from 'react-native';
import { SafeAreaView } from 'react-native-safe-area-context';
import { Theme, useActiveColors } from '../../../theme/Theme';
import { useGlobalState } from '../../../context/GlobalState';
import { horizontalScale, verticalScale, moderateScale } from '../../../utils/responsive';
import {
  ChevronLeft,
  MessageSquare,
  PhoneCall,
  Plus,
  Trash2,
  Camera,
  ChevronDown,
  ChevronUp,
  Search,
  MapPin,
  Clock,
  Navigation,
  HelpCircle,
  AlertCircle,
  User,
  Phone,
  Mail,
  Settings
} from 'lucide-react-native';
import GlassCard from '../../../components/GlassCard';
import Animated, { FadeInDown, FadeInUp } from 'react-native-reanimated';
import ScalePress from '../../../components/ScalePress';
import CustomBottomSheet from '../../../components/CustomBottomSheet';
import { useSupport } from './useSupport';
import { styles } from './styles';
import { ISSUE_TYPES, FAQ_CATEGORIES } from './constants';

export default function SupportScreen({ navigation }) {
  const activeColors = useActiveColors();
  const isDark = activeColors.isDark;
  const { themeMode } = useGlobalState();

  const {
    selectedIssue,
    feedbackText,
    setFeedbackText,
    attachedImages,
    searchQuery,
    setSearchQuery,
    activeFaqId,
    tickets,
    selectedTicket,
    selectedFaq,
    isIssueSheetVisible,

    issueSheetRef,
    ticketDetailSheetRef,
    faqDetailSheetRef,

    handleOpenIssueSheet,
    handleSelectIssue,
    handleCloseIssueSheet,
    handleOpenTicketDetail,
    handleCloseTicketDetail,
    handleCloseFaqDetail,
    handleAttachImage,
    handleRemoveImage,
    handleSubmitFeedback,
    handleCallAdvisor,
    handleEmailSupport,
    handleNavigateMaps,
    handleToggleFaq,
    handleApproveCloseTicket
  } = useSupport();

  // Lọc câu hỏi FAQ động theo tìm kiếm
  const filteredFaqCategories = FAQ_CATEGORIES.map(category => {
    const matchedItems = category.items.filter(item =>
      item.question.toLowerCase().includes(searchQuery.toLowerCase()) ||
      item.answer.toLowerCase().includes(searchQuery.toLowerCase())
    );
    return {
      ...category,
      items: matchedItems
    };
  }).filter(category => category.items.length > 0);

  const isFormValid = feedbackText.trim().length > 0;

  return (
    <SafeAreaView style={[styles.container, { backgroundColor: activeColors.background }]} edges={['top']}>
      {/* HEADER */}
      <View style={[styles.header, { paddingHorizontal: 20, justifyContent: 'space-between', width: '100%' }]}>
        <View style={{ flexDirection: 'row', alignItems: 'center' }}>
          <TouchableOpacity
            style={[styles.backBtn, { backgroundColor: isDark ? 'rgba(255,255,255,0.05)' : 'rgba(0,0,0,0.03)', borderRadius: 12, width: 44, height: 44, justifyContent: 'center', alignItems: 'center', marginRight: 15 }]}
            onPress={() => navigation.goBack()}
          >
            <ChevronLeft color={activeColors.text} size={moderateScale(24)} />
          </TouchableOpacity>
          <Text style={[styles.title, { color: activeColors.text }]}>Hỗ trợ khách hàng</Text>
        </View>
        <TouchableOpacity
          style={{ width: 44, height: 44, justifyContent: 'center', alignItems: 'center', backgroundColor: isDark ? 'rgba(255,255,255,0.05)' : 'rgba(0,0,0,0.03)', borderRadius: 12 }}
          onPress={() => navigation.navigate('CustomerHome', { screen: 'Profile', params: { openSettings: true } })}
        >
          <Settings color={activeColors.text} size={22} />
        </TouchableOpacity>
      </View>

      <ScrollView
        showsVerticalScrollIndicator={false}
        contentContainerStyle={styles.scrollContent}
        keyboardShouldPersistTaps="handled"
      >

        {/* TẦNG 1: SPOTLIGHT – TRỢ LÝ SỐ AI & KẾT NỐI CHUYÊN VIÊN */}
        <Animated.View entering={FadeInUp.duration(600).delay(100)}>
          <GlassCard style={styles.spotlightCard}>
            <Text style={[styles.greeting, { color: activeColors.subtext }]}>Xin chào, Anh Khôi 👋</Text>
            <Text style={[styles.spotlightTitle, { color: activeColors.text }]}>AnhEmMotor có thể giúp gì cho bạn hôm nay?</Text>

            <View style={styles.spotlightActions}>
              <ScalePress style={styles.primaryBtn} onPress={() => navigation.navigate('AIChat')}>
                <MessageSquare color="#fff" size={moderateScale(18)} />
                <Text style={styles.primaryBtnText}>Hỏi Trợ lý AI</Text>
              </ScalePress>

              <ScalePress
                style={[styles.secondaryBtn, { backgroundColor: isDark ? 'rgba(255, 255, 255, 0.08)' : 'rgba(0, 0, 0, 0.04)', borderColor: activeColors.border }]}
                onPress={() => navigation.navigate('ContactStaff')}
              >
                <User color={Theme.staticColors.primary} size={moderateScale(18)} />
                <Text style={[styles.secondaryBtnText, { color: activeColors.text }]}>Hỗ Trợ Viên</Text>
              </ScalePress>
            </View>
          </GlassCard>
        </Animated.View>

        {/* TẦNG 2: VẬN HÀNH – FORM GỬI PHẢN HỒI VĂN BẢN */}
        <Animated.View entering={FadeInDown.duration(600).delay(200)}>
          <Text style={[styles.sectionLabel, { color: activeColors.text }]}>Gửi ý kiến phản hồi 📣</Text>
          <GlassCard style={styles.formCard}>
            {/* Chọn Nhóm Vấn đề */}
            <Text style={[styles.dropdownLabel, { color: activeColors.subtext }]}>Nhóm vấn đề cần hỗ trợ</Text>
            <TouchableOpacity
              style={[styles.dropdownSelector, { backgroundColor: isDark ? 'rgba(0,0,0,0.25)' : '#F8FAFC', borderColor: activeColors.border }]}
              onPress={handleOpenIssueSheet}
              activeOpacity={0.7}
            >
              <Text style={[styles.dropdownVal, { color: activeColors.text }]}>{selectedIssue}</Text>
              <ChevronDown color={activeColors.subtext} size={moderateScale(18)} />
            </TouchableOpacity>

            {/* Viết Nội dung */}
            <Text style={[styles.dropdownLabel, { color: activeColors.subtext }]}>Mô tả chi tiết yêu cầu</Text>
            <View style={[styles.textareaContainer, { backgroundColor: isDark ? 'rgba(0,0,0,0.25)' : '#F8FAFC', borderColor: activeColors.border }]}>
              <TextInput
                style={[styles.textarea, { color: activeColors.text }]}
                placeholder="Vui lòng nhập phản hồi, ý kiến đóng góp hoặc thắc mắc của bạn (tối đa 500 ký tự)..."
                placeholderTextColor={isDark ? 'rgba(255, 255, 255, 0.3)' : 'rgba(0, 0, 0, 0.4)'}
                multiline
                maxLength={500}
                value={feedbackText}
                onChangeText={setFeedbackText}
              />
              <Text style={[styles.charCounter, { color: activeColors.subtext }]}>{feedbackText.length}/500</Text>
            </View>

            {/* Đính kèm hình ảnh và Gửi */}
            <View style={styles.formFooter}>
              <View style={styles.attachRow}>
                <TouchableOpacity
                  style={[styles.attachIconBtn, { backgroundColor: isDark ? 'rgba(255,255,255,0.05)' : '#F8FAFC', borderWidth: 1, borderColor: activeColors.border }]}
                  onPress={handleAttachImage}
                  activeOpacity={0.7}
                >
                  <Camera color={Theme.staticColors.primary} size={moderateScale(20)} />
                </TouchableOpacity>

                {attachedImages.map((uri, idx) => (
                  <View key={idx} style={styles.attachPreview}>
                    <Image source={{ uri }} style={styles.attachImg} />
                    <TouchableOpacity
                      style={styles.attachRemove}
                      onPress={() => handleRemoveImage(idx)}
                    >
                      <Text style={styles.attachRemoveText}>×</Text>
                    </TouchableOpacity>
                  </View>
                ))}
              </View>

              <TouchableOpacity
                style={isFormValid ? styles.submitBtn : [styles.submitBtnDisabled, { backgroundColor: isDark ? 'rgba(255, 255, 255, 0.05)' : '#E2E8F0', borderColor: activeColors.border }]}
                onPress={handleSubmitFeedback}
                disabled={!isFormValid}
                activeOpacity={0.8}
              >
                <Text style={isFormValid ? styles.submitBtnText : [styles.submitBtnTextDisabled, { color: isDark ? 'rgba(255, 255, 255, 0.25)' : '#94A3B8' }]}>Gửi phản hồi</Text>
              </TouchableOpacity>
            </View>
          </GlassCard>
        </Animated.View>

        {/* LỊCH SỬ YÊU CẦU - PHẢN HỒI CỦA TÔI */}
        {tickets.length > 0 && (
          <Animated.View entering={FadeInDown.duration(600).delay(250)}>
            <Text style={[styles.sectionLabel, { color: activeColors.text }]}>Phản hồi của tôi ({tickets.length})</Text>
            <ScrollView
              horizontal
              showsHorizontalScrollIndicator={false}
              contentContainerStyle={styles.ticketScroll}
            >
              {tickets.map((ticket) => (
                <TouchableOpacity
                  key={ticket.id}
                  activeOpacity={0.9}
                  onPress={() => handleOpenTicketDetail(ticket)}
                >
                  <GlassCard style={styles.ticketCard}>
                    <View style={styles.ticketHeader}>
                      <Text style={styles.ticketType}>{ticket.issueType}</Text>
                      <Text style={[
                        styles.ticketStatus,
                        { color: ticket.status === 'resolved' ? Theme.staticColors.success : Theme.staticColors.warning }
                      ]}>
                        {ticket.statusLabel}
                      </Text>
                    </View>
                    <Text style={[styles.ticketContent, { color: activeColors.text }]} numberOfLines={2}>
                      {ticket.content}
                    </Text>
                    <View style={styles.ticketFooter}>
                      <Text style={[styles.ticketDate, { color: activeColors.subtext }]}>{ticket.date}</Text>
                      <Text style={styles.ticketCta}>Xem chi tiết</Text>
                    </View>
                  </GlassCard>
                </TouchableOpacity>
              ))}
            </ScrollView>
          </Animated.View>
        )}

        {/* TẦNG 3: TỰ PHỤC VỤ – TRUNG TÂM CÂU HỎI THƯỜNG GẶP (SMART FAQ) */}
        <Animated.View entering={FadeInDown.duration(600).delay(300)} style={{ marginTop: verticalScale(15) }}>
          <Text style={[styles.sectionLabel, { color: activeColors.text }]}>Câu hỏi thường gặp FAQ 🔍</Text>

          {/* Thanh tìm kiếm thông minh */}
          <View style={[styles.searchBox, { backgroundColor: isDark ? 'rgba(255,255,255,0.03)' : 'rgba(0,0,0,0.02)', borderColor: activeColors.border }]}>
            <Search color={activeColors.subtext} size={moderateScale(18)} />
            <TextInput
              style={[styles.searchInput, { color: activeColors.text }]}
              placeholder="Tìm kiếm thủ tục trả góp, bảo hành, xe sạch..."
              placeholderTextColor={isDark ? 'rgba(255,255,255,0.35)' : 'rgba(0,0,0,0.35)'}
              value={searchQuery}
              onChangeText={setSearchQuery}
            />
          </View>

          {/* Danh sách câu hỏi thả xuống */}
          {filteredFaqCategories.length > 0 ? (
            filteredFaqCategories.map((category) => (
              <View key={category.id} style={styles.faqCatBox}>
                <View style={styles.faqCatHeader}>
                  <category.icon color={category.iconColor} size={moderateScale(18)} />
                  <Text style={[styles.faqCatTitle, { color: activeColors.text }]}>{category.title}</Text>
                </View>

                {category.items.map((item) => {
                  return (
                    <View key={item.id} style={[styles.faqAccordion, { backgroundColor: activeColors.card, borderColor: activeColors.border, borderWidth: 1 }]}>
                      <TouchableOpacity
                        style={styles.faqHeader}
                        onPress={() => handleToggleFaq(item.id)}
                        activeOpacity={0.7}
                      >
                        <Text style={[styles.faqQuestion, { color: activeColors.text }]}>{item.question}</Text>
                        <ChevronDown color={activeColors.subtext} size={moderateScale(16)} />
                      </TouchableOpacity>
                    </View>
                  );
                })}
              </View>
            ))
          ) : (
            <View style={{ alignItems: 'center', paddingVertical: 20 }}>
              <HelpCircle color={isDark ? 'rgba(255,255,255,0.2)' : 'rgba(0,0,0,0.2)'} size={40} />
              <Text style={{ color: activeColors.subtext, fontSize: 13, marginTop: 10 }}>Không tìm thấy câu hỏi phù hợp</Text>
            </View>
          )}
        </Animated.View>

        {/* TẦNG 4: HỆ THỐNG – BẢN ĐỒ & THÔNG TIN CỬA HÀNG */}
        <Animated.View entering={FadeInDown.duration(600).delay(400)} style={{ marginTop: verticalScale(15) }}>
          <Text style={[styles.sectionLabel, { color: activeColors.text }]}>Cửa hàng kinh doanh xe máy 📍</Text>
          <GlassCard style={styles.systemCard}>
            <View style={styles.systemHeader}>
              <MapPin color={Theme.staticColors.primary} size={moderateScale(20)} />
              <Text style={[styles.systemTitle, { color: activeColors.text }]}>Showroom AnhEmMotor Biên Hòa</Text>
            </View>
            <Text style={[styles.systemAddress, { color: activeColors.text }]}>Số 28, Đường Đồng Khởi, Phường Tân Phong, Thành phố Biên Hòa, Tỉnh Đồng Nai</Text>

            <View style={[styles.systemHeader, { marginBottom: verticalScale(15), marginTop: verticalScale(5) }]}>
              <Clock color={activeColors.subtext} size={moderateScale(16)} />
              <Text style={[styles.systemHours, { color: activeColors.subtext }]}>Giờ mở cửa: 08:00 - 20:00 (Hằng ngày)</Text>
            </View>

            {/* Hotline & Email liên hệ */}
            <View style={[styles.systemContactContainer, { borderTopColor: activeColors.border }]}>
              <TouchableOpacity
                style={styles.systemContactItem}
                onPress={handleCallAdvisor}
                activeOpacity={0.7}
              >
                <Phone color="#10B981" size={moderateScale(16)} />
                <Text style={[styles.systemContactText, { color: activeColors.text }]}>Hotline: 0912 345 678</Text>
              </TouchableOpacity>

              <TouchableOpacity
                style={styles.systemContactItem}
                onPress={handleEmailSupport}
                activeOpacity={0.7}
              >
                <Mail color="#E31B23" size={moderateScale(16)} />
                <Text style={[styles.systemContactText, { color: activeColors.text }]}>support@anhemmotor.vn</Text>
              </TouchableOpacity>
            </View>

            <TouchableOpacity
              style={styles.mapBtn}
              onPress={handleNavigateMaps}
              activeOpacity={0.8}
            >
              <Navigation color="#fff" size={moderateScale(18)} />
              <Text style={styles.mapBtnText}>Chỉ đường qua Google Maps</Text>
            </TouchableOpacity>
          </GlassCard>
        </Animated.View>

        <View style={{ height: verticalScale(60) }} />
      </ScrollView>

      {/* BOTTOM SHEET: CHỌN PHÂN LOẠI PHẢN HỒI (TẦNG 2) */}
      {isIssueSheetVisible && (
        <CustomBottomSheet
          ref={issueSheetRef}
          title="Chọn nhóm vấn đề hỗ trợ"
          onClose={handleCloseIssueSheet}
          themeMode={themeMode}
        >
          <View style={styles.sheetContent}>
            {ISSUE_TYPES.map((issue) => {
              const isSelected = selectedIssue === issue;
              return (
                <TouchableOpacity
                  key={issue}
                  style={[styles.sheetOption, { borderBottomColor: activeColors.border }]}
                  onPress={() => handleSelectIssue(issue)}
                  activeOpacity={0.7}
                >
                  <Text style={[isSelected ? styles.sheetOptionSelectedText : styles.sheetOptionText, { color: activeColors.text }]}>
                    {issue}
                  </Text>
                </TouchableOpacity>
              );
            })}
          </View>
        </CustomBottomSheet>
      )}

      {/* BOTTOM SHEET: CHI TIẾT PHẢN HỒI & CRM REPLY (TẦNG 2) */}
      {selectedTicket && (
        <CustomBottomSheet
          ref={ticketDetailSheetRef}
          title="Chi tiết yêu cầu hỗ trợ"
          onClose={handleCloseTicketDetail}
          themeMode={themeMode}
        >
          <View style={styles.sheetContent}>
            <View style={styles.ticketDetailBox}>
              <View style={styles.ticketDetailMeta}>
                <Text style={{ color: Theme.staticColors.primary, fontSize: 13, fontWeight: 'bold' }}>
                  Yêu cầu: {selectedTicket.issueType}
                </Text>
                <Text style={{ color: activeColors.subtext, fontSize: 12 }}>
                  Ngày gửi: {selectedTicket.date}
                </Text>
              </View>

              <Text style={{ color: activeColors.subtext, fontSize: 12, marginBottom: 5 }}>Nội dung của bạn:</Text>
              <Text style={[styles.ticketDetailContent, { color: activeColors.text }]}>{selectedTicket.content}</Text>

              <View style={[styles.chatBox, { backgroundColor: isDark ? 'rgba(0,0,0,0.2)' : 'rgba(0,0,0,0.03)' }]}>
                <Text style={styles.chatAuthor}>Phản hồi từ CRM Admin:</Text>
                <Text style={[styles.chatText, { color: activeColors.text }]}>{selectedTicket.reply}</Text>
              </View>

              {/* Nút tương tác 2 chiều */}
              <View style={styles.sheetActionRow}>
                <TouchableOpacity
                  style={styles.sheetCloseBtn}
                  onPress={() => handleApproveCloseTicket(selectedTicket.id)}
                  activeOpacity={0.8}
                >
                  <Text style={styles.sheetCloseBtnText}>✓ Duyệt đóng ca</Text>
                </TouchableOpacity>
                <TouchableOpacity
                  style={[styles.sheetDiscussBtn, { backgroundColor: isDark ? 'rgba(255, 255, 255, 0.08)' : 'rgba(0, 0, 0, 0.04)', borderColor: activeColors.border }]}
                  onPress={() => {
                    handleCloseTicketDetail();
                    navigation.navigate('ContactStaff', { ticketId: selectedTicket.id, trackingToken: selectedTicket.trackingToken });
                  }}
                  activeOpacity={0.8}
                >
                  <Text style={[styles.sheetDiscussBtnText, { color: activeColors.text }]}>💬 Thảo luận thêm</Text>
                </TouchableOpacity>
              </View>
            </View>
          </View>
        </CustomBottomSheet>
      )}

      {/* BOTTOM SHEET: CHI TIẾT CÂU HỎI THƯỜNG GẶP FAQ (TẦNG 3 - QUY TẮC VÀNG 1) */}
      {selectedFaq && (
        <CustomBottomSheet
          ref={faqDetailSheetRef}
          title="Chi tiết câu hỏi thường gặp"
          onClose={handleCloseFaqDetail}
          themeMode={themeMode}
        >
          <View style={styles.sheetContent}>
            <Text style={[styles.faqDetailQuestion, { color: activeColors.text }]}>❓ {selectedFaq.question}</Text>
            <View style={[styles.faqDetailAnswerBox, { backgroundColor: isDark ? 'rgba(255,255,255,0.03)' : 'rgba(0,0,0,0.02)', borderColor: activeColors.border }]}>
              <Text style={[styles.faqDetailAnswer, { color: activeColors.text }]}>{selectedFaq.answer}</Text>
            </View>
          </View>
        </CustomBottomSheet>
      )}

    </SafeAreaView>
  );
}

import { useState, useRef, useCallback } from 'react';
import { Linking, Alert } from 'react-native';
import { ISSUE_TYPES, INITIAL_TICKETS, FAQ_CATEGORIES } from './constants';
import { contactApi } from '../../../api/contactApi';
import AsyncStorage from '@react-native-async-storage/async-storage';
import { useDependency } from '../../../di/DependencyContext';
import { useEffect } from 'react';

export const useSupport = () => {
  // Trạng thái Form phản hồi
  const [selectedIssue, setSelectedIssue] = useState(ISSUE_TYPES[0]);
  const [feedbackText, setFeedbackText] = useState('');
  const [attachedImages, setAttachedImages] = useState([]);
  
  // Trạng thái tìm kiếm FAQ
  const [searchQuery, setSearchQuery] = useState('');
  
  // Trạng thái Accordion FAQ
  const [activeFaqId, setActiveFaqId] = useState(null);

  // Danh sách phản hồi của tôi (Tickets)
  const [tickets, setTickets] = useState(INITIAL_TICKETS);
  
  // Quản lý Bottom Sheets
  const [selectedTicket, setSelectedTicket] = useState(null);
  const [selectedFaq, setSelectedFaq] = useState(null);
  const [isIssueSheetVisible, setIsIssueSheetVisible] = useState(false);
  const [isSubmitting, setIsSubmitting] = useState(false);
  
  const issueSheetRef = useRef(null);
  const ticketDetailSheetRef = useRef(null);
  const faqDetailSheetRef = useRef(null);

  const { getProfileUseCase } = useDependency();

  // Load tickets from AsyncStorage on mount
  useEffect(() => {
    const loadTickets = async () => {
      try {
        const stored = await AsyncStorage.getItem('anhem-mobile-support-tickets');
        if (stored) {
          const parsedTickets = JSON.parse(stored);
          setTickets(parsedTickets);
          
          // Optionally, we could fetch tracking for all of them here to update status
          // But to keep it simple, we'll just show them as stored and update when clicked
        } else {
          setTickets([]);
        }
      } catch (e) {
        console.warn('Failed to load tickets', e);
      }
    };
    loadTickets();
  }, []);

  const saveTickets = async (newTickets) => {
    setTickets(newTickets);
    try {
      await AsyncStorage.setItem('anhem-mobile-support-tickets', JSON.stringify(newTickets));
    } catch (e) {
      console.warn('Failed to save tickets', e);
    }
  };

  // Mở/Đóng Bottom Sheet chọn loại vấn đề
  const handleOpenIssueSheet = useCallback(() => {
    setIsIssueSheetVisible(true);
    setTimeout(() => {
      issueSheetRef.current?.show();
    }, 50);
  }, []);

  const handleSelectIssue = useCallback((issue) => {
    setSelectedIssue(issue);
    issueSheetRef.current?.hide();
    setTimeout(() => {
      setIsIssueSheetVisible(false);
    }, 300);
  }, []);

  const handleCloseIssueSheet = useCallback(() => {
    setIsIssueSheetVisible(false);
  }, []);

  // Mở/Đóng Bottom Sheet chi tiết Ticket
  const handleOpenTicketDetail = useCallback(async (ticket) => {
    // Try to fetch latest tracking status
    try {
      const tracking = await contactApi.getSupportTracking(ticket.id, ticket.trackingToken);
      if (tracking) {
        // Update ticket with latest tracking data
        const updatedTicket = {
          ...ticket,
          status: tracking.status,
          statusLabel: tracking.statusLabel || (tracking.status === 'Resolved' ? '✓ Đã giải quyết' : '⏱️ Đang xử lý'),
          reply: tracking.replies && tracking.replies.length > 0 ? tracking.replies[0].message : ticket.reply
        };
        setSelectedTicket(updatedTicket);
      } else {
        setSelectedTicket(ticket);
      }
    } catch (e) {
      console.warn('Failed to fetch tracking', e);
      setSelectedTicket(ticket);
    }
    
    setTimeout(() => {
      ticketDetailSheetRef.current?.show();
    }, 50);
  }, []);

  const handleCloseTicketDetail = useCallback(() => {
    setSelectedTicket(null);
  }, []);

  // Chụp ảnh đính kèm giả lập
  const handleAttachImage = useCallback(() => {
    const fakeImages = [
      'https://images.unsplash.com/photo-1558981403-c5f9899a28bc?q=80&w=200',
      'https://images.unsplash.com/photo-1558981806-ec527fa84c39?q=80&w=200'
    ];
    // Đính kèm ngẫu nhiên
    const randomImg = fakeImages[Math.floor(Math.random() * fakeImages.length)];
    if (attachedImages.length >= 3) {
      Alert.alert('Giới hạn ảnh', 'Bạn chỉ được đính kèm tối đa 3 hình ảnh minh chứng.');
      return;
    }
    setAttachedImages((prev) => [...prev, randomImg]);
  }, [attachedImages]);

  const handleRemoveImage = useCallback((indexToRemove) => {
    setAttachedImages((prev) => prev.filter((_, idx) => idx !== indexToRemove));
  }, []);

  // Gửi phản hồi lên CRM
  const handleSubmitFeedback = useCallback(async () => {
    if (!feedbackText.trim() || isSubmitting) return;

    setIsSubmitting(true);
    try {
      let userProfile = {};
      try {
        const profile = await getProfileUseCase.execute();
        if (profile) userProfile = profile;
      } catch (e) {
        // Ignore if user not logged in or profile fetch fails
      }

      const response = await contactApi.submitSupportRequest({
        fullName: userProfile.name || 'Khách hàng',
        phoneNumber: userProfile.phone || '',
        email: userProfile.email || 'guest@anhemmotor.vn',
        subject: `Yêu cầu hỗ trợ: ${selectedIssue}`,
        category: selectedIssue,
        content: feedbackText,
      });

      if (response && response.value && response.value.id) {
        const data = response.value;
        const newTicket = {
          id: data.id,
          trackingToken: data.trackingToken,
          issueType: selectedIssue,
          content: feedbackText,
          date: new Date().toLocaleDateString('vi-VN'),
          status: 'pending',
          statusLabel: '⏱️ Đang xử lý',
          reply: 'Hệ thống CRM của AnhEmMotor đã ghi nhận phản hồi của bạn. Một chuyên viên hỗ trợ đang được điều phối để xử lý yêu cầu của bạn.'
        };

        saveTickets([newTicket, ...tickets]);
        setFeedbackText('');
        setAttachedImages([]);
        
        Alert.alert(
          'Gửi thành công! 🎉',
          `Ý kiến của bạn đã được gửi trực tiếp đến hệ thống CRM. Mã theo dõi: ${data.id}`
        );
      } else {
        throw new Error('Invalid response');
      }
    } catch (error) {
      console.error('Submit feedback error', error);
      Alert.alert('Lỗi', 'Không thể gửi phản hồi. Vui lòng thử lại sau.');
    } finally {
      setIsSubmitting(false);
    }
  }, [feedbackText, selectedIssue, tickets, isSubmitting, getProfileUseCase]);

  // Gọi Cố vấn trực tiếp qua số hotline
  const handleCallAdvisor = useCallback(async () => {
    const url = 'tel:0912345678';
    try {
      const supported = await Linking.canOpenURL(url);
      if (supported) {
        await Linking.openURL(url);
      } else {
        Alert.alert('Không hỗ trợ', 'Thiết bị không hỗ trợ cuộc gọi trực tiếp. Hotline: 0912 345 678');
      }
    } catch {
      Alert.alert('Lỗi', 'Không thể thực hiện cuộc gọi.');
    }
  }, []);

  // Gửi Email hỗ trợ
  const handleEmailSupport = useCallback(async () => {
    const url = 'mailto:support@anhemmotor.vn';
    try {
      await Linking.openURL(url);
    } catch {
      Alert.alert('Lỗi', 'Không thể mở ứng dụng Email.');
    }
  }, []);

  // Chỉ đường Google Maps đến Showroom Biên Hòa
  const handleNavigateMaps = useCallback(async () => {
    // Showroom AnhEmMotor Biên Hòa: 10.9575, 106.8427
    const lat = 10.9575;
    const lng = 106.8427;
    const label = 'Showroom AnhEmMotor Bien Hoa';
    
    const url = `https://www.google.com/maps/search/?api=1&query=${lat},${lng}`;
    try {
      await Linking.openURL(url);
    } catch {
      Alert.alert('Lỗi', 'Không thể khởi chạy Google Maps.');
    }
  }, []);

  // Mở/Đóng Bottom Sheet chi tiết FAQ (trượt từ dưới lên theo quy tắc vàng)
  const handleCloseFaqDetail = useCallback(() => {
    setSelectedFaq(null);
  }, []);

  // Bấm vào FAQ sẽ mở Bottom Sheet trượt từ dưới lên
  const handleToggleFaq = useCallback((id) => {
    for (const category of FAQ_CATEGORIES) {
      const found = category.items.find(item => item.id === id);
      if (found) {
        setSelectedFaq(found);
        setTimeout(() => {
          faqDetailSheetRef.current?.show();
        }, 50);
        break;
      }
    }
  }, []);

  // Khách hàng Duyệt đóng ca trong tương tác 2 chiều
  const handleApproveCloseTicket = useCallback(async (ticketId) => {
    const ticketToClose = tickets.find(t => t.id === ticketId);
    if (!ticketToClose) return;

    try {
      // Opt-in: send rating to backend
      await contactApi.rateSupportEmployee(ticketId, ticketToClose.trackingToken, 5, 'Đã đóng yêu cầu');
      
      const newTickets = tickets.map(t => {
        if (t.id === ticketId) {
          return { ...t, status: 'resolved', statusLabel: '✓ Đã giải quyết' };
        }
        return t;
      });
      saveTickets(newTickets);
      ticketDetailSheetRef.current?.hide();
      setTimeout(() => {
        setSelectedTicket(null);
        Alert.alert('Thành công 🎉', 'Bạn đã duyệt đóng ca hỗ trợ này. Cảm ơn ý kiến của bạn!');
      }, 300);
    } catch (e) {
      Alert.alert('Lỗi', 'Không thể đóng yêu cầu lúc này.');
    }
  }, [tickets]);

  return {
    selectedIssue,
    feedbackText,
    setFeedbackText,
    attachedImages,
    searchQuery,
    setSearchQuery,
    activeFaqId,
    tickets,
    selectedTicket,
    selectedFaq,
    isIssueSheetVisible,
    isSubmitting,
    
    issueSheetRef,
    ticketDetailSheetRef,
    faqDetailSheetRef,
    
    handleOpenIssueSheet,
    handleSelectIssue,
    handleCloseIssueSheet,
    handleOpenTicketDetail,
    handleCloseTicketDetail,
    handleCloseFaqDetail,
    handleAttachImage,
    handleRemoveImage,
    handleSubmitFeedback,
    handleCallAdvisor,
    handleEmailSupport,
    handleNavigateMaps,
    handleToggleFaq,
    handleApproveCloseTicket
  };
};

import React, { useState, useRef } from 'react';
import { 
  StyleSheet, 
  Text, 
  View, 
  Image, 
  ScrollView, 
  TouchableOpacity, 
  Dimensions, 
  Platform,
  StatusBar
} from 'react-native';
import { useTheme } from '../../theme/Theme'; // Import useTheme
import { 
  ChevronLeft, 
  ShieldCheck, 
  Zap, 
  RotateCcw
} from 'lucide-react-native';
import { LinearGradient } from 'expo-linear-gradient';
import { BlurView } from 'expo-blur';
import GlassCard from '../../components/GlassCard';
import Animated, { FadeIn, FadeInDown } from 'react-native-reanimated';
import ScalePress from '../../components/ScalePress';
import FinanceCalculator from '../../components/FinanceCalculator';
import Toast from '../../components/Toast';

const { width: screenWidth, height: screenHeight } = Dimensions.get('window');

export default function VehicleDetailScreen({ navigation, route }) {
  const { motor, isOwned } = route.params || {};
  const theme = useTheme();
  const styles = getStyles(theme); // Use the useTheme hook
  const [activeTab, setActiveTab] = useState('overview');
  const [selectedColor, setSelectedColor] = useState(motor?.colors?.[0]?.id || 'default');
  const [rotationIndex, setRotationIndex] = useState(0);
  const toastRef = useRef(null);
  
  const lastX = useRef(0);
  const motorFrames = motor?.frames || [motor?.img];

  // Raw Responder System - Higher reliability than PanGestureHandler for scrolling
  const handleTouchStart = (e) => {
    lastX.current = e.nativeEvent.pageX;
  };

  const handleTouchMove = (e) => {
    const currentX = e.nativeEvent.pageX;
    const diff = lastX.current - currentX;
    const sensitivity = 20;

    if (Math.abs(diff) > sensitivity) {
      const direction = diff > 0 ? 1 : -1;
      setRotationIndex(prev => {
        let next = (prev + direction) % motorFrames.length;
        if (next < 0) next = motorFrames.length - 1;
        return next;
      });
      lastX.current = currentX;
    }
  };

  const currentImage = motor?.frames 
    ? motorFrames[rotationIndex] 
    : (motor?.colors?.find(c => c.id === selectedColor)?.img || motor?.img);

  return (
    <View style={getStyles(theme).container}>
      <StatusBar barStyle="light-content" />
      
      <ScrollView 
        style={styles.scrollView}
        contentContainerStyle={styles.scrollContent}
        showsVerticalScrollIndicator={true}
        bounces={true}
        overScrollMode="always"
      >
        {/* IMAGE HEADER / 360 AREA */}
        <View style={getStyles(theme).header}>
          <View
            style={styles.imageWrapper}
            onMoveShouldSetResponder={(evt) => {
              const { dx, dy } = evt.nativeEvent;
              return Math.abs(dx) > Math.abs(dy) && Math.abs(dx) > 10;
            }}
            onResponderGrant={handleTouchStart}
            onResponderMove={handleTouchMove}
          >
            <Animated.Image 
              entering={FadeIn.duration(800)} // This is fine
              source={currentImage} 
              style={getStyles(theme).mainImage} 
              resizeMode="contain"
            />
            
            {motor?.frames && (
              <View style={getStyles(theme).rotationBadge}>
                <RotateCcw color="#fff" size={14} />
                <Text style={getStyles(theme).rotationText}>Vuốt ngang để xoay 360°</Text>
              </View>
            )}
          </View>

          <TouchableOpacity
            style={getStyles(theme).backBtn}
            onPress={() => navigation.goBack()}
          >
            <BlurView intensity={30} tint="dark" style={StyleSheet.absoluteFill} />
            <ChevronLeft color="#fff" size={24} />
          </TouchableOpacity>
        </View>

        {/* CONTENT AREA */}
        <View style={[getStyles(theme).content, { backgroundColor: theme.colors.background }]}>
          <View style={getStyles(theme).titleRow}>
            <View style={{ flex: 1 }}>
              <Text style={[getStyles(theme).name, { color: theme.colors.text }]}>{motor?.name || 'Motorcycle'}</Text>
              <Text style={[getStyles(theme).category, { color: theme.colors.subtext }]}>{motor?.brand} • High Performance</Text>
            </View>
            <Text style={[getStyles(theme).price, { color: theme.colors.primary }]}>{motor?.price}</Text>
          </View>

          {/* COLOR SELECTOR */}
          {!isOwned && motor?.colors && (
            <View style={getStyles(theme).section}>
              <Text style={[getStyles(theme).sectionTitle, { color: theme.colors.text }]}>Màu sắc</Text>
              <View style={getStyles(theme).colorGrid}>
                {motor.colors.map(c => (
                  <TouchableOpacity 
                    key={c.id} 
                    style={[styles.colorItem, selectedColor === c.id && styles.activeColor]}
                    onPress={() => setSelectedColor(c.id)}
                  >
                    <View style={[styles.colorDot, { backgroundColor: c.hex }]} />
                    <Text style={[getStyles(theme).colorLabel, { color: theme.colors.subtext }, selectedColor === c.id && getStyles(theme).activeLabel]}>{c.label}</Text>
                  </TouchableOpacity>
                ))}
              </View>
            </View>
          )}

          {/* TAB SYSTEM */}
          <View style={[getStyles(theme).tabBar, { backgroundColor: theme.colors.border + '33' }]}>
            {['overview', 'specs', 'finance'].map(tab => (
              <TouchableOpacity 
                key={tab} 
                style={[styles.tab, activeTab === tab && styles.activeTab]}
                onPress={() => setActiveTab(tab)}
              >
                <Text style={[styles.tabText, activeTab === tab && styles.activeTabText]}>
                  {tab === 'overview' ? 'Tổng quan' : tab === 'specs' ? 'Thông số' : 'Trả góp'} {/* Use getStyles for tabText */}
                </Text>
              </TouchableOpacity>
            ))}
          </View>

          {activeTab === 'overview' && (
            <Animated.View entering={FadeInDown} style={getStyles(theme).tabContent}>
              <Text style={[getStyles(theme).description, { color: theme.colors.subtext }]}>{motor?.description}</Text>
              <GlassCard style={[getStyles(theme).featureCard, { backgroundColor: theme.colors.card, borderColor: theme.colors.border }]} intensity={15}>
                <View style={getStyles(theme).featureItem}>
                  <Zap color={theme.colors.primary} size={22} />
                  <View style={getStyles(theme).fInfo}>
                    <Text style={[getStyles(theme).fTitle, { color: theme.colors.text }]}>Công nghệ Sugomi</Text>
                    <Text style={[getStyles(theme).fDesc, { color: theme.colors.subtext }]}>Thiết kế tối ưu khí động học và sức mạnh.</Text>
                  </View>
                </View>
                <View style={getStyles(theme).featureItem}>
                  <ShieldCheck color="#10B981" size={22} />
                  <View style={getStyles(theme).fInfo}>
                    <Text style={[getStyles(theme).fTitle, { color: theme.colors.text }]}>Bảo hành 3 năm</Text>
                    <Text style={[getStyles(theme).fDesc, { color: theme.colors.subtext }]}>Chính sách bảo hành toàn diện từ AnhEmMotor.</Text>
                  </View>
                </View>
              </GlassCard>
            </Animated.View>
          )}

          {activeTab === 'specs' && (
            <Animated.View entering={FadeInDown} style={getStyles(theme).specGrid}>
              {motor?.specs?.map((s, i) => (
                <View key={i} style={[getStyles(theme).specItem, { backgroundColor: theme.colors.card + '33' }]}>
                  <Text style={[getStyles(theme).specVal, { color: theme.colors.text }]}>{s.value}</Text>
                  <Text style={[getStyles(theme).specLabel, { color: theme.colors.subtext }]}>{s.label}</Text>
                </View>
              ))}
            </Animated.View>
          )}

          {activeTab === 'finance' && (
            <Animated.View entering={FadeInDown}>
              <FinanceCalculator 
                vehiclePrice={450000000} 
                onAction={() => toastRef.current?.show('Yêu cầu đã được gửi!')}
              />
            </Animated.View>
          )}

          {/* BOTTOM ACTIONS - INSIDE SCROLLVIEW */}
          <View style={getStyles(theme).actionArea}>
            <ScalePress style={getStyles(theme).mainBtn} onPress={() => navigation.navigate('Booking')}>
              <LinearGradient colors={[theme.colors.primary, theme.colors.primary + 'AA']} style={getStyles(theme).gradient}>
                <Text style={getStyles(theme).btnText}>{isOwned ? 'Đặt lịch bảo dưỡng' : 'Đăng ký lái thử ngay'}</Text>
              </LinearGradient>
            </ScalePress>
            <Text style={styles.footerHint}>* Giá trên đã bao gồm VAT, chưa bao gồm phí trước bạ.</Text>
          </View>
        </View>
      </ScrollView>

      <Toast ref={toastRef} />
    </View>
  );
}

